# 【算法思路】使用滑动窗口实现二维卷积前向累加并按公式计算卷积输出特征图空间高宽。
import numpy as np
# 按填充与步幅滑动卷积核求局部内积
def conv2d_forward(img, kernel, stride=1, padding=0):
    img = np.array(img); kernel = np.array(kernel)
    if padding > 0: img = np.pad(img, padding, mode="constant")
    H, W = img.shape; KH, KW = kernel.shape
    out_h = (H - KH)//stride + 1; out_w = (W - KW)//stride + 1
    out = np.zeros((out_h, out_w))
    for i in range(out_h):
        for j in range(out_w):
            out[i,j] = np.sum(img[i*stride:i*stride+KH, j*stride:j*stride+KW] * kernel)
    return out
# 利用 (H+2p-k)//s+1 推导输出尺寸
def compute_output_shape(H, W, KH, KW, stride, padding):
    oh = (H + 2*padding - KH)//stride + 1
    ow = (W + 2*padding - KW)//stride + 1
    return (oh, ow)

# 【算法思路】对比 ReLU、LeakyReLU、ELU 与 Swish 四种平滑或分片线性激活函数及其一阶导数。
import numpy as np

# 标准线性整流
def relu(x):
    return np.maximum(0.0, np.asarray(x, dtype=float))

# 负半轴保留 alpha 斜率
def leaky_relu(x, alpha=0.01):
    x = np.asarray(x, dtype=float)
    return np.where(x > 0, x, alpha * x)

# 负半轴指数平滑饱和
def elu(x, alpha=1.0):
    x = np.asarray(x, dtype=float)
    return np.where(x > 0, x, alpha * (np.exp(np.clip(x, -100, 100)) - 1.0))

# x 与 sigmoid(x) 自门控乘积
def swish(x):
    x = np.asarray(x, dtype=float)
    s = 1.0 / (1.0 + np.exp(-np.clip(x, -100, 100)))
    return x * s

def _swish_grad(x):
    s = 1.0 / (1.0 + np.exp(-np.clip(x, -100, 100)))
    return s + x * s * (1.0 - s)

# 分激活类型返回对应解析导数向量
def gradient(activation, x):
    x = np.asarray(x, dtype=float)
    if activation == "relu":
        return (x > 0).astype(float)
    if activation in ("leaky", "leaky_relu"):
        return np.where(x > 0, 1.0, 0.01)
    if activation == "elu":
        return np.where(x > 0, 1.0, np.exp(np.clip(x, -100, 100)))
    if activation == "swish":
        return _swish_grad(x)
    return x

# 【算法思路】用调节因子 (1-pt)^gamma 对高置信易分样本降权实现 Focal Loss，并对比不同聚焦指数变化。
import numpy as np

# 提取对应真实类别概率并乘以困难样本权重系数
def focal_loss(y_pred, y_true, gamma=2.0):
    y_pred = np.clip(np.asarray(y_pred, dtype=float), 1e-10, 1 - 1e-10)
    y_true = np.asarray(y_true, dtype=float)
    pt = np.where(y_true == 1, y_pred, 1 - y_pred)
    return float(np.mean(-((1 - pt) ** gamma) * np.log(pt)))

# 令 gamma=0 特化为标准交叉熵
def cross_entropy_loss(y_pred, y_true):
    return focal_loss(y_pred, y_true, 0.0)

# 同时返回 CE 与 gamma=1/2 的焦点损失
def compare_losses(y_pred, y_true):
    return {
        "ce": round(cross_entropy_loss(y_pred, y_true), 4),
        "fl_g1": round(focal_loss(y_pred, y_true, 1.0), 4),
        "fl_g2": round(focal_loss(y_pred, y_true, 2.0), 4),
    }

# 【算法思路】在经典的病态香蕉谷 Rosenbrock 函数上对比 SGD、动量 SGD 与 Adam 三种优化轨迹。
import numpy as np
# 计算二维 Rosenbrock 函数值
def rosenbrock(x, y, a=1, b=100):
    return (a-x)**2 + b*(y-x**2)**2
# 返回在 (x, y) 处的解析梯度向量
def rosenbrock_grad(x, y, a=1, b=100):
    dx = -2*(a-x) - 4*b*x*(y-x**2)
    dy = 2*b*(y-x**2)
    return np.array([dx, dy])
# 朴素梯度下降
def sgd(x0, lr=0.001, steps=100):
    x = np.array(x0, dtype=float); hist = [x.copy()]
    for _ in range(steps):
        g = rosenbrock_grad(x[0], x[1])
        x -= lr*g; hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}
# 动量加速版梯度下降
def momentum_sgd(x0, lr=0.001, beta=0.9, steps=100):
    x = np.array(x0, dtype=float); v = np.zeros_like(x); hist = [x.copy()]
    for _ in range(steps):
        g = rosenbrock_grad(x[0], x[1])
        v = beta*v + g; x -= lr*v; hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}
# 自适应矩估计 Adam 迭代追踪优化路径
def adam_optimizer(x0, lr=0.01, steps=100):
    x = np.array(x0, dtype=float); m=v=np.zeros_like(x); t=0; hist=[x.copy()]
    for _ in range(steps):
        t+=1; g=rosenbrock_grad(x[0],x[1])
        m=0.9*m+0.1*g; v=0.999*v+0.001*g**2
        mh=m/(1-0.9**t); vh=v/(1-0.999**t)
        x -= lr*mh/(np.sqrt(vh)+1e-8); hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}

# 【算法思路】实现通用倒置 Dropout 算子以及基于多次随机前向采样估计预测均值与不确定性方差的 MC Dropout。
import numpy as np

# 按训练标志及 keep_prob 生成归一化随机掩码
def dropout(x, keep_prob=0.5, training=True):
    x = np.asarray(x, dtype=float)
    if not training or keep_prob >= 1:
        return x
    if keep_prob <= 0:
        return np.zeros_like(x)
    mask = (np.random.rand(*x.shape) < keep_prob).astype(float) / keep_prob
    return x * mask

# 开启随机采样收集多次预测计算均值与预测方差
def mc_dropout_predict(model, x, n_samples=10):
    preds = []
    for _ in range(n_samples):
        if hasattr(model, "apply"):
            model.apply(lambda m: setattr(m, "training", True))
        preds.append(model(x))
    mean = np.mean(preds, axis=0)
    var = np.var(preds, axis=0)
    return {
        "mean": mean.tolist() if hasattr(mean, "tolist") else mean,
        "variance": var.tolist() if hasattr(var, "tolist") else var,
    }
